#include <cstdint>
#include <format>
#include <iostream>

// Third-party class: raw ADC counts, 0 to 4095 across 0 to 1000 kPa. We cannot change it.
class LegacyPressureSensor {
 public:
  explicit LegacyPressureSensor(std::int32_t raw_counts) : raw_counts_(raw_counts) {}
  [[nodiscard]] std::int32_t raw_counts() const { return raw_counts_; }

 private:
  std::int32_t raw_counts_;
};

// The interface our own code is written against.
class PressureSensor {
 public:
  PressureSensor() = default;
  PressureSensor(const PressureSensor&) = delete;
  PressureSensor& operator=(const PressureSensor&) = delete;
  virtual ~PressureSensor() = default;
  [[nodiscard]] virtual std::int32_t kilopascals() const = 0;
};

// The adapter: a PressureSensor on the outside, a LegacyPressureSensor on the inside.
class PressureSensorAdapter final : public PressureSensor {
 public:
  explicit PressureSensorAdapter(const LegacyPressureSensor& legacy) : legacy_(legacy) {}
  [[nodiscard]] std::int32_t kilopascals() const override { return legacy_.raw_counts() * 1000 / 4095; }

 private:
  const LegacyPressureSensor& legacy_;
};

void report(const PressureSensor& sensor) { std::cout << std::format("{} kPa\n", sensor.kilopascals()); }

int main() {
  const LegacyPressureSensor legacy(2048);
  const PressureSensorAdapter adapter(legacy);
  report(adapter);
}

