#include <cstdint>
#include <format>
#include <iostream>
#include <memory>
#include <vector>

// The project's own type: an exact tick count, never a float.
struct Ticks {
  std::int64_t count;
};

// The interface the rest of the code calls. It knows nothing about any vendor.
class WheelEncoder {
 public:
  WheelEncoder() = default;
  WheelEncoder(const WheelEncoder&) = delete;
  WheelEncoder& operator=(const WheelEncoder&) = delete;
  virtual ~WheelEncoder() = default;
  [[nodiscard]] virtual Ticks ticks() const = 0;
};

// The vendor's class: 32-bit counts, its own name for the same idea. We cannot change it.
class VendorEncoder {
 public:
  explicit VendorEncoder(std::int32_t count) : count_(count) {}
  [[nodiscard]] std::int32_t count() const { return count_; }

 private:
  std::int32_t count_;
};

// Object adapter: holds the vendor type, exposes only WheelEncoder.
class VendorEncoderAdapter final : public WheelEncoder {
 public:
  explicit VendorEncoderAdapter(const VendorEncoder& legacy) : legacy_(legacy) {}
  [[nodiscard]] Ticks ticks() const override { return Ticks{.count = legacy_.count()}; }

 private:
  const VendorEncoder& legacy_;
};

// Class adapter: inherits the vendor type privately instead of holding it, and the target publicly.
class VendorEncoderClassAdapter final : private VendorEncoder, public WheelEncoder {
 public:
  using VendorEncoder::VendorEncoder;
  [[nodiscard]] Ticks ticks() const override { return Ticks{.count = count()}; }
};

// Enough for one call site: no polymorphism, so no class is needed at all.
[[nodiscard]] Ticks ticks_from(const VendorEncoder& legacy) { return Ticks{.count = legacy.count()}; }

int main() {
  const VendorEncoder legacy(150000);

  const VendorEncoderAdapter object_adapter(legacy);
  std::cout << std::format("object adapter through WheelEncoder&: {}\n", object_adapter.ticks().count);

  const VendorEncoderClassAdapter class_adapter(150000);
  std::cout << std::format("class adapter through WheelEncoder&:  {}\n", class_adapter.ticks().count);

  std::cout << std::format("one call site, no interface needed: {}\n", ticks_from(legacy).count);

  std::vector<std::unique_ptr<WheelEncoder>> fleet;
  fleet.push_back(std::make_unique<VendorEncoderAdapter>(legacy));
  fleet.push_back(std::make_unique<VendorEncoderClassAdapter>(150000));
  for (const auto& encoder : fleet) std::cout << std::format("fleet member reports {} ticks\n", encoder->ticks().count);

  std::cout << std::format("sizeof VendorEncoderAdapter:      {}\n", sizeof(VendorEncoderAdapter));
  std::cout << std::format("sizeof VendorEncoderClassAdapter: {}\n", sizeof(VendorEncoderClassAdapter));
}

