#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <utility>
#include <vector>

// The vendor probe: tenths of a Fahrenheit degree as a double, -999.0 when disconnected.
// It is final and we cannot change it.
class LegacyFahrenheitProbe final {
 public:
  explicit LegacyFahrenheitProbe(double reading_f) : reading_f_(reading_f) {}
  [[nodiscard]] double read_fahrenheit() const { return reading_f_; }

 private:
  double reading_f_;
};

constexpr double kDisconnected = -999.0;

// The interface the rest of the project calls: exact millidegrees Celsius, or nothing when there is no probe.
class TemperatureSensor {
 public:
  TemperatureSensor() = default;
  TemperatureSensor(const TemperatureSensor&) = delete;
  TemperatureSensor& operator=(const TemperatureSensor&) = delete;
  virtual ~TemperatureSensor() = default;
  [[nodiscard]] virtual std::optional<std::int32_t> millidegrees_c() const = 0;
};

// The object adapter: a TemperatureSensor on the outside, a LegacyFahrenheitProbe on the inside.
class FahrenheitAdapter final : public TemperatureSensor {
 public:
  explicit FahrenheitAdapter(const LegacyFahrenheitProbe& legacy) : legacy_(legacy) {}

  [[nodiscard]] std::optional<std::int32_t> millidegrees_c() const override {
    const double raw_f = legacy_.read_fahrenheit();
    if (raw_f == kDisconnected) return std::nullopt;
    // Round to the nearest millidegree Fahrenheit once, at this boundary; everything after is exact integers.
    const std::int64_t milli_f = static_cast<std::int64_t>(raw_f * 1000.0 + (raw_f >= 0.0 ? 0.5 : -0.5));
    return static_cast<std::int32_t>((milli_f - 32'000) * 5 / 9);
  }

 private:
  const LegacyFahrenheitProbe& legacy_;
};

[[nodiscard]] std::string shown(const std::optional<std::int32_t>& milli_c) {
  if (!milli_c) return "no probe";
  const std::int32_t whole = *milli_c / 1000;
  const std::int32_t thousandths = *milli_c % 1000;
  return std::format("{}.{:03} C", whole, thousandths < 0 ? -thousandths : thousandths);
}

int main() {
  const std::vector<std::pair<double, std::optional<std::int32_t>>> cases{
      {98.6, 37000}, {32.0, 0}, {212.0, 100000}, {-40.0, -40000}, {kDisconnected, std::nullopt}};

  for (const auto& [raw_f, expected] : cases) {
    const LegacyFahrenheitProbe probe(raw_f);
    const FahrenheitAdapter adapter(probe);
    const std::optional<std::int32_t> got = adapter.millidegrees_c();
    std::cout << std::format("{:>7.1f} F -> {:<10} expected {:<10} match {}\n", raw_f, shown(got), shown(expected),
                             got == expected);
  }
}

#include <cstdint>
#include <format>
#include <iostream>
#include <optional>

class LegacyFahrenheitProbe final {
 public:
  explicit LegacyFahrenheitProbe(double reading_f) : reading_f_(reading_f) {}
  [[nodiscard]] double read_fahrenheit() const { return reading_f_; }

 private:
  double reading_f_;
};

constexpr double kDisconnected = -999.0;

class TemperatureSensor {
 public:
  TemperatureSensor() = default;
  TemperatureSensor(const TemperatureSensor&) = delete;
  TemperatureSensor& operator=(const TemperatureSensor&) = delete;
  virtual ~TemperatureSensor() = default;
  [[nodiscard]] virtual std::optional<std::int32_t> millidegrees_c() const = 0;
};

// The constant looks right and reads well. 5 / 9 divides two ints first: the result is 0, not 0.5555...
constexpr double kCPerF = 5 / 9;

class BuggyAdapter final : public TemperatureSensor {
 public:
  explicit BuggyAdapter(const LegacyFahrenheitProbe& legacy) : legacy_(legacy) {}
  [[nodiscard]] std::optional<std::int32_t> millidegrees_c() const override {
    const double raw_f = legacy_.read_fahrenheit();
    if (raw_f == kDisconnected) return std::nullopt;
    return static_cast<std::int32_t>((raw_f - 32.0) * kCPerF * 1000.0);
  }

 private:
  const LegacyFahrenheitProbe& legacy_;
};

int main() {
  const LegacyFahrenheitProbe body_temp(98.6);
  const BuggyAdapter adapter(body_temp);
  std::cout << std::format("kCPerF = {}\n", kCPerF);
  std::cout << std::format("98.6 F through the buggy adapter: {} millidegrees C\n", *adapter.millidegrees_c());
}

#include <cstdint>
#include <format>
#include <iostream>

struct Ticks {
  std::int64_t count;
};

class WheelEncoder {
 public:
  WheelEncoder() = default;
  WheelEncoder(const WheelEncoder&) = delete;
  WheelEncoder& operator=(const WheelEncoder&) = delete;
  virtual ~WheelEncoder() = default;
  [[nodiscard]] virtual Ticks ticks() const = 0;
};

// Mounted backward: the vendor's count falls while the wheel turns forward.
class VendorEncoder {
 public:
  explicit VendorEncoder(std::int32_t count) : count_(count) {}
  [[nodiscard]] std::int32_t count() const { return count_; }

 private:
  std::int32_t count_;
};

// The mistake: VendorEncoder inherited publicly instead of privately. Its own count() stays public.
class VendorEncoderClassAdapter final : public VendorEncoder, public WheelEncoder {
 public:
  using VendorEncoder::VendorEncoder;
  [[nodiscard]] Ticks ticks() const override { return Ticks{.count = -count()}; }  // corrects the sign
};

int main() {
  const VendorEncoderClassAdapter adapter(4000);
  const WheelEncoder& through_the_port = adapter;
  std::cout << std::format("through WheelEncoder&, corrected: {}\n", through_the_port.ticks().count);
  std::cout << std::format("through the adapter's own count(), uncorrected: {}\n", adapter.count());
}
